/* =========================================================
   RESPONSIVE DESIGN – MOBILE FIRST / TABLET / DESKTOP
   ========================================================= */

/* Grundsätzlich flexible Medien und Inhalte */
html{
  -webkit-text-size-adjust:100%;
  text-size-adjust:100%;
}
body{
  overflow-x:hidden;
}
img,svg,canvas,video{
  max-width:100%;
  height:auto;
}
button,input,select,textarea{
  max-width:100%;
}
.page{
  width:min(1180px,calc(100% - 24px));
  margin-inline:auto;
}

/* Flexible Typografie */
h1{
  font-size:clamp(2rem,5vw,3.65rem);
  line-height:1.05;
}
h2{
  font-size:clamp(1.25rem,2.8vw,1.75rem);
}
h3{
  font-size:clamp(1rem,2.2vw,1.2rem);
}
p,.q-text,.focus,.note{
  overflow-wrap:anywhere;
  hyphens:auto;
}

/* Touchfreundliche Mindestgrößen */
.btn,
.nav a,
.opt label,
.field input,
.course-link{
  min-height:44px;
}
.btn{
  padding:12px 18px;
}
.opt label{
  min-width:44px;
}

/* Header flexibler */
.hero,.result-hero{
  min-height:clamp(420px,58vw,620px);
  background-position:center center!important;
}
.hero-grid{
  width:100%;
}
.header-copy,
.hero > div[style*="max-width"],
.result-hero > p,
.result-meta{
  max-width:min(760px,100%);
}
.scale-info{
  grid-template-columns:repeat(5,minmax(0,1fr));
}

/* Dashboard */
.dashboard{
  grid-template-columns:repeat(4,minmax(0,1fr));
}

/* Fragenlayout */
.question{
  grid-template-columns:minmax(0,1fr) auto;
}
.scale{
  grid-template-columns:repeat(5,minmax(44px,48px));
}

/* Tabellen */
.result-table{
  min-width:720px;
}
.table-panel > div[style*="overflow-x:auto"]{
  -webkit-overflow-scrolling:touch;
}

/* Kurs- und Empfehlungskarten */
.course-grid,
.recommendation-grid{
  grid-template-columns:repeat(3,minmax(0,1fr));
}

/* Große Desktops */
@media (min-width:1400px){
  .page{
    width:min(1280px,calc(100% - 48px));
  }
  .hero,.result-hero{
    min-height:620px;
  }
}

/* Tablets */
@media (max-width:1024px){
  .page{
    width:min(100% - 24px,1100px);
  }
  .hero,.result-hero{
    min-height:520px;
    padding:120px 28px 30px;
  }
  .dashboard{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }
  .scale-info{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }
  .course-grid,
  .recommendation-grid{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }
  .result-summary-grid{
    grid-template-columns:1fr;
  }
  .summary-list{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }
}

/* Kleine Tablets / große Smartphones */
@media (max-width:768px){
  .page{
    width:min(100% - 16px,100%);
    padding-top:8px;
  }

  .hero,.result-hero{
    min-height:auto;
    padding:112px 18px 24px;
    border-radius:18px;
    background-position:66% center!important;
  }

  .brand-logo-passion{
    top:14px!important;
    left:14px!important;
    width:132px!important;
  }

  .brand-logo-volker{
    top:12px!important;
    right:14px!important;
    width:58px!important;
  }

  .hero-grid{
    justify-content:flex-end;
  }

  .status{
    font-size:.82rem;
    padding:8px 11px;
  }

  .scale-info{
    grid-template-columns:1fr;
    gap:8px;
  }

  .scale-chip{
    padding:11px 12px;
  }

  .dashboard{
    grid-template-columns:1fr 1fr;
    gap:10px;
  }

  .card,.panel{
    padding:15px;
  }

  .value{
    font-size:1.45rem;
  }

  .nav{
    gap:7px;
    padding-bottom:12px;
    scroll-snap-type:x proximity;
  }

  .nav a{
    scroll-snap-align:start;
    font-size:.8rem;
    padding:9px 12px;
  }

  .category-head{
    grid-template-columns:1fr auto;
    padding:17px 15px;
    gap:12px;
  }

  .category-number{
    width:31px;
    height:31px;
  }

  .score-box{
    min-width:92px;
    padding:9px;
  }

  .question{
    grid-template-columns:1fr;
    gap:14px;
    padding:17px 15px;
  }

  .scale{
    width:100%;
    grid-template-columns:repeat(5,minmax(44px,1fr));
    gap:7px;
  }

  .opt label{
    width:100%;
    height:46px;
  }

  .category-foot{
    padding:0 15px 17px;
    flex-direction:column;
    gap:5px;
  }

  .submission-panel{
    padding:20px 16px;
    border-radius:18px;
  }

  .profile-grid{
    grid-template-columns:1fr;
  }

  .actions,
  .report-actions{
    flex-direction:column;
    align-items:stretch;
  }

  .action-group{
    display:grid;
    grid-template-columns:1fr;
  }

  .btn{
    width:100%;
    justify-content:center;
    text-align:center;
  }

  .summary-list{
    grid-template-columns:1fr;
  }

  .chart-row{
    grid-template-columns:1fr 54px;
    gap:8px;
  }

  .chart-track{
    grid-column:1 / -1;
    grid-row:2;
  }

  .course-grid,
  .recommendation-grid{
    grid-template-columns:1fr;
  }

  .course-category-head{
    flex-direction:column;
    align-items:flex-start;
  }

  .score-circle{
    width:160px;
    height:160px;
  }

  .score-circle strong{
    font-size:2.5rem;
  }

  .result-meta{
    gap:7px;
  }

  .result-meta span{
    font-size:.78rem;
  }
}

/* Kleine Smartphones */
@media (max-width:480px){
  .page{
    width:100%;
    padding-inline:8px;
  }

  .hero,.result-hero{
    padding:104px 14px 20px;
    border-radius:14px;
    background-position:72% center!important;
  }

  h1{
    font-size:clamp(1.75rem,9vw,2.35rem);
  }

  .hero p,.result-hero p{
    font-size:.94rem;
    line-height:1.55;
  }

  .dashboard{
    grid-template-columns:1fr;
  }

  .category-head{
    grid-template-columns:1fr;
  }

  .score-box{
    width:100%;
  }

  .scale{
    gap:5px;
  }

  .opt label{
    height:44px;
    font-size:.95rem;
  }

  .field input{
    height:46px;
  }

  .course-card,
  .recommendation-card,
  .summary-box{
    padding:14px;
  }

  .result-table{
    font-size:.82rem;
  }

  .result-table th,
  .result-table td{
    padding:9px 7px;
  }
}

/* Sehr kleine Geräte */
@media (max-width:360px){
  .brand-logo-passion{
    width:116px!important;
  }

  .brand-logo-volker{
    width:52px!important;
  }

  .hero,.result-hero{
    padding-top:94px;
  }

  .scale{
    grid-template-columns:repeat(5,minmax(40px,1fr));
  }

  .opt label{
    min-width:40px;
    height:42px;
  }
}

/* Querformat auf Mobilgeräten */
@media (max-height:520px) and (orientation:landscape){
  .hero,.result-hero{
    min-height:auto;
    padding-top:92px;
    background-position:center 36%!important;
  }
}

/* Reduzierte Bewegung */
@media (prefers-reduced-motion:reduce){
  html{
    scroll-behavior:auto;
  }
  *,*::before,*::after{
    animation-duration:.01ms!important;
    animation-iteration-count:1!important;
    transition-duration:.01ms!important;
  }
}


/* MOBILE FUNKTIONS-FIX */
@media (max-width:768px){
  #assessmentView,#surveyForm,#submissionPanel{
    display:block!important;
    visibility:visible!important;
    opacity:1!important;
    position:relative!important;
    z-index:1!important;
  }
  #surveyForm{width:100%;overflow:visible!important}
  .category{display:block!important;width:100%;overflow:visible!important}
  .question{display:grid!important}
  .scale{display:grid!important;position:relative!important;z-index:2!important}
  .opt{display:block!important;position:relative!important;min-width:0!important}
  .opt input{position:absolute!important;opacity:0!important;width:1px!important;height:1px!important}
  .opt label{
    display:grid!important;
    pointer-events:auto!important;
    touch-action:manipulation!important;
    user-select:none!important;
    -webkit-user-select:none!important;
  }
  #submissionPanel{margin-bottom:28px!important}
  #submitBtn{
    display:flex!important;
    align-items:center!important;
    justify-content:center!important;
    width:100%!important;
    min-height:52px!important;
    position:relative!important;
    z-index:5!important;
    pointer-events:auto!important;
    touch-action:manipulation!important;
  }
  #resultsView{width:100%!important}
  .report-actions{padding-bottom:24px!important}
}



